const calcularIndicador = (codigo, criterio, nombre, filterFn, tipo) => {
  for (const year of years) {
    const itemsYear = year === 'Total' ? allItems : allItems.filter(r => getYear(r) === year);
    const filtered = filterFn(itemsYear);

    let valor = 0;
    if (tipo === 'unique') {
      valor = countUnique(filtered, 'creamos_id');
    } else if (tipo === 'count') {
      valor = filtered.length;
    } else if (tipo === 'avg_escala') {
      const vals = filtered.filter(r => r.promedio_escala !== undefined).map(r => r.promedio_escala);
      valor = vals.length > 0 ? Math.round(vals.reduce((a,b) => a+b, 0) / vals.length * 100) / 100 : 0;
    } else if (tipo === 'prepost') {
      const pre = formFilters['Pre_Test'](itemsYear);
      const post = formFilters['Post_Test'](itemsYear);
      const pairs = pre.map(pr => {
        const po = post.find(p =>
          (pr.creamos_id && pr.creamos_id !== '' && p.creamos_id === pr.creamos_id) ||
          (pr.nombre_completo && p.nombre_completo &&
           pr.nombre_completo.toLowerCase().trim() === p.nombre_completo.toLowerCase().trim())
        );
        return { pre: pr, post: po };
      }).filter(p => p.post && p.pre.puntaje_total !== undefined && p.post.puntaje_total !== undefined);

      const improved = pairs.filter(p => p.post.puntaje_total > p.pre.puntaje_total);
      valor = pairs.length > 0 ? Math.round(improved.length / pairs.length * 100) : 0;
    }

    const targets = TARGETS[codigo] || {};
    const targetVal = targets.Target_Compromiso;
    const pctAvance = (targetVal && targetVal > 0 && valor > 0) ? Math.round(valor / targetVal * 100) : 0;
    const desag = desagregarColumnas(filtered);

    indicadores.push({
      Codigo: codigo,
      Anio: year,
      Criterio: criterio,
      Indicador: nombre,
      Valor: valor,
      Target_Compromiso: targets.Target_Compromiso || 0,
      Target_Aspiracional: targets.Target_Aspiracional || 0,
      Pct_Avance: pctAvance,
      Tipo_Medicion: tipo === 'avg_escala' ? 'Promedio' : tipo === 'prepost' ? 'Porcentaje' : tipo === 'count' ? 'Conteo' : 'Conteo_Unicos',
      // --- Género (cada uno su columna) ---
      Genero_Femenino: desag.Genero_Femenino,
      Genero_Masculino: desag.Genero_Masculino,
      Genero_Otro: desag.Genero_Otro,
      Genero_Sin_Dato: desag.Genero_Sin_Dato,
      // --- Nivel educativo (cada uno su columna) ---
      Nivel_Primaria: desag.Nivel_Primaria,
      Nivel_Basico: desag.Nivel_Basico,
      Nivel_Diversificado: desag.Nivel_Diversificado,
      Nivel_Universitario: desag.Nivel_Universitario,
      Nivel_Otro: desag.Nivel_Otro,
      Nivel_Sin_Dato: desag.Nivel_Sin_Dato,
      // --- Rango de edad (cada uno su columna) ---
      Edad_Menor_18: desag.Edad_Menor_18,
      Edad_18_24: desag.Edad_18_24,
      Edad_25_30: desag.Edad_25_30,
      Edad_Mayor_30: desag.Edad_Mayor_30,
      Edad_Sin_Dato: desag.Edad_Sin_Dato,
      // --- Meta ---
      Fecha_Calculo: hoy,
      Nivel: 'IL'
    });
  }
};

